'use strict';

// 信封与负载 Schema 校验。严格模式：拒绝未知字段、未知模型、非 HTTPS Endpoint。

const { ALLOWED_MODELS, isAllowedModel } = require('@aigc-desk/contracts');
const {
  FORMAT,
  VERSION,
  CIPHER_NAME,
  SIGNATURE_NAME,
  IV_BYTES,
  AUTH_TAG_BYTES,
  ED25519_SIGNATURE_BYTES,
  BASE64_PATTERN
} = require('./constants.cjs');

function schemaError(code, message) {
  const error = new Error(message);
  error.code = code;
  error.status = 400;
  return error;
}

function assertPlainObject(value, code, message) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw schemaError(code, message);
  }
}

function assertNoUnknownKeys(obj, allowed, code) {
  for (const key of Object.keys(obj)) {
    if (!allowed.includes(key)) {
      throw schemaError(code, `未知字段：${key}`);
    }
  }
}

function decodeBase64(value, expectedBytes, code, message) {
  if (typeof value !== 'string' || !BASE64_PATTERN.test(value)) {
    throw schemaError(code, message);
  }
  const buf = Buffer.from(value, 'base64');
  if (buf.length !== expectedBytes) {
    throw schemaError(code, message);
  }
  return buf;
}

// 校验公开信封（验签前调用，不接触明文）
function validateEnvelopeSchema(envelope) {
  assertPlainObject(envelope, 'ENVELOPE_INVALID', '信封必须是对象');

  assertNoUnknownKeys(envelope, ['format', 'version', 'packageId', 'createdAt', 'cipher', 'ciphertext', 'signature'], 'ENVELOPE_UNKNOWN_FIELD');

  if (envelope.format !== FORMAT) throw schemaError('ENVELOPE_INVALID', 'format 无效');
  if (envelope.version !== VERSION) throw schemaError('ENVELOPE_UNSUPPORTED_VERSION', 'version 不受支持');

  if (typeof envelope.packageId !== 'string' || !envelope.packageId || envelope.packageId.length > 64) {
    throw schemaError('ENVELOPE_INVALID', 'packageId 无效');
  }
  if (typeof envelope.createdAt !== 'string' || Number.isNaN(Date.parse(envelope.createdAt))) {
    throw schemaError('ENVELOPE_INVALID', 'createdAt 无效');
  }

  // cipher
  assertPlainObject(envelope.cipher, 'ENVELOPE_INVALID', 'cipher 无效');
  assertNoUnknownKeys(envelope.cipher, ['name', 'iv', 'authTag'], 'ENVELOPE_UNKNOWN_FIELD');
  if (envelope.cipher.name !== CIPHER_NAME) throw schemaError('ENVELOPE_INVALID', 'cipher.name 无效');
  decodeBase64(envelope.cipher.iv, IV_BYTES, 'ENVELOPE_INVALID', 'iv 无效');
  decodeBase64(envelope.cipher.authTag, AUTH_TAG_BYTES, 'ENVELOPE_INVALID', 'authTag 无效');

  // ciphertext
  if (typeof envelope.ciphertext !== 'string' || !BASE64_PATTERN.test(envelope.ciphertext) || envelope.ciphertext.length === 0) {
    throw schemaError('ENVELOPE_INVALID', 'ciphertext 无效');
  }

  // signature
  assertPlainObject(envelope.signature, 'ENVELOPE_INVALID', 'signature 无效');
  assertNoUnknownKeys(envelope.signature, ['name', 'keyId', 'value'], 'ENVELOPE_UNKNOWN_FIELD');
  if (envelope.signature.name !== SIGNATURE_NAME) throw schemaError('ENVELOPE_INVALID', 'signature.name 无效');
  if (typeof envelope.signature.keyId !== 'string' || !envelope.signature.keyId) {
    throw schemaError('ENVELOPE_INVALID', 'signature.keyId 无效');
  }
  decodeBase64(envelope.signature.value, ED25519_SIGNATURE_BYTES, 'ENVELOPE_INVALID', 'signature.value 无效');

  return envelope;
}

// 校验 HTTPS Endpoint（baseURL 白名单）
function assertHttpsBaseUrl(value, allowedHosts = null) {
  if (typeof value !== 'string' || !value) {
    throw schemaError('PAYLOAD_INVALID', 'baseURL 无效');
  }
  let url;
  try {
    url = new URL(value);
  } catch (_) {
    throw schemaError('PAYLOAD_INVALID', 'baseURL 无效');
  }
  if (url.protocol !== 'https:') {
    throw schemaError('PAYLOAD_HTTP_ENDPOINT_FORBIDDEN', 'baseURL 必须是 HTTPS');
  }
  if (!url.hostname) {
    throw schemaError('PAYLOAD_INVALID', 'baseURL 缺少主机名');
  }
  if (url.username || url.password) {
    throw schemaError('PAYLOAD_INVALID', 'baseURL 不得含用户名或密码');
  }
  if (allowedHosts && Array.isArray(allowedHosts) && allowedHosts.length > 0) {
    const host = url.hostname.toLowerCase();
    if (!allowedHosts.map(h => String(h).toLowerCase()).includes(host)) {
      throw schemaError('PAYLOAD_ENDPOINT_NOT_ALLOWED', 'baseURL 不在允许的 Endpoint 白名单');
    }
  }
  return value;
}

function validateKeyEntry(key, allowedHosts) {
  assertPlainObject(key, 'PAYLOAD_INVALID', 'key 项无效');
  assertNoUnknownKeys(key, ['id', 'baseURL', 'apiKey', 'models', 'priority'], 'PAYLOAD_UNKNOWN_FIELD');

  if (typeof key.id !== 'string' || !key.id || key.id.length > 64) {
    throw schemaError('PAYLOAD_INVALID', 'key.id 无效');
  }
  assertHttpsBaseUrl(key.baseURL, allowedHosts);

  if (typeof key.apiKey !== 'string' || !key.apiKey) {
    throw schemaError('PAYLOAD_INVALID', 'key.apiKey 无效');
  }

  if (!Array.isArray(key.models) || key.models.length === 0) {
    throw schemaError('PAYLOAD_INVALID', 'key.models 无效');
  }
  for (const m of key.models) {
    if (!isAllowedModel(m)) {
      throw schemaError('PAYLOAD_UNKNOWN_MODEL', `未知模型：${m}`);
    }
  }

  if (!Number.isSafeInteger(key.priority) || key.priority < 0) {
    throw schemaError('PAYLOAD_INVALID', 'key.priority 必须是非负整数');
  }

  return key;
}

// 校验解密后的负载（解密成功后才调用，明文仅内存）
function validatePayloadSchema(payload, allowedHosts = null) {
  assertPlainObject(payload, 'PAYLOAD_INVALID', '负载必须是对象');
  assertNoUnknownKeys(payload, ['label', 'allowedModels', 'keys', 'localGateway'], 'PAYLOAD_UNKNOWN_FIELD');

  if (typeof payload.label !== 'string' || !payload.label || payload.label.length > 128) {
    throw schemaError('PAYLOAD_INVALID', 'label 无效');
  }

  if (!Array.isArray(payload.allowedModels) || payload.allowedModels.length === 0) {
    throw schemaError('PAYLOAD_INVALID', 'allowedModels 无效');
  }
  for (const m of payload.allowedModels) {
    if (!isAllowedModel(m)) {
      throw schemaError('PAYLOAD_UNKNOWN_MODEL', `未知模型：${m}`);
    }
  }

  if (!Array.isArray(payload.keys) || payload.keys.length === 0) {
    throw schemaError('PAYLOAD_INVALID', 'keys 不能为空');
  }
  const ids = new Set();
  for (const key of payload.keys) {
    validateKeyEntry(key, allowedHosts);
    if (ids.has(key.id)) throw schemaError('PAYLOAD_INVALID', `重复 key.id：${key.id}`);
    ids.add(key.id);
  }

  // localGateway
  assertPlainObject(payload.localGateway, 'PAYLOAD_INVALID', 'localGateway 无效');
  assertNoUnknownKeys(payload.localGateway, ['enabled', 'port'], 'PAYLOAD_UNKNOWN_FIELD');
  if (typeof payload.localGateway.enabled !== 'boolean') {
    throw schemaError('PAYLOAD_INVALID', 'localGateway.enabled 无效');
  }
  if (payload.localGateway.port !== 3461) {
    throw schemaError('PAYLOAD_INVALID', 'localGateway.port 必须是 3461');
  }

  return payload;
}

module.exports = {
  schemaError,
  assertHttpsBaseUrl,
  validateEnvelopeSchema,
  validatePayloadSchema,
  decodeBase64
};
